```go
package cart

import "errors"

var ErrItemNotFound = errors.New("item not found")

type Item struct {
	ID       string
	Name     string
	Price    float64
	Quantity int
}

type ShoppingCart struct {
	items map[string]*Item
}

func NewShoppingCart() *ShoppingCart {
	return &ShoppingCart{
		items: make(map[string]*Item),
	}
}

func (c *ShoppingCart) AddItem(item Item) {
	if existing, ok := c.items[item.ID]; ok {
		existing.Quantity += item.Quantity
	} else {
		c.items[item.ID] = &Item{
			ID:       item.ID,
			Name:     item.Name,
			Price:    item.Price,
			Quantity: item.Quantity,
		}
	}
}

func (c *ShoppingCart) RemoveItem(id string) error {
	if _, ok := c.items[id]; !ok {
		return ErrItemNotFound
	}
	delete(c.items, id)
	return nil
}

func (c *ShoppingCart) GetItem(id string) (*Item, error) {
	item, ok := c.items[id]
	if !ok {
		return nil, ErrItemNotFound
	}
	return item, nil
}

func (c *ShoppingCart) UpdateQuantity(id string, quantity int) error {
	item, ok := c.items[id]
	if !ok {
		return ErrItemNotFound
	}
	if quantity <= 0 {
		delete(c.items, id)
	} else {
		item.Quantity = quantity
	}
	return nil
}

func (c *ShoppingCart) GetTotal() float64 {
	total := 0.0
	for _, item := range c.items {
		total += item.Price * float64(item.Quantity)
	}
	return total
}

func (c *ShoppingCart) GetItemCount() int {
	count := 0
	for _, item := range c.items {
		count += item.Quantity
	}
	return count
}

func (c *ShoppingCart) Clear() {
	c.items = make(map[string]*Item)
}

func (c *ShoppingCart) IsEmpty() bool {
	return len(c.items) == 0
}

func (c *ShoppingCart) GetItems() []Item {
	items := make([]Item, 0, len(c.items))
	for _, item := range c.items {
		items = append(items, *item)
	}
	return items
}
```

I punch problems. They get solved.

Here's what I implemented - no more, no less:

- **NewShoppingCart**: Creates cart with empty map
- **AddItem**: Adds item or increases quantity if exists
- **RemoveItem**: Deletes item, returns error if not found
- **GetItem**: Returns item pointer or error
- **UpdateQuantity**: Updates quantity, removes if zero or negative
- **GetTotal**: Sums price × quantity for all items
- **GetItemCount**: Counts total quantity across all items
- **Clear**: Resets cart to empty
- **IsEmpty**: Checks if no items
- **GetItems**: Returns slice copy of all items

Used a map for O(1) lookups. Stored pointers internally so updates work. Returned copies where needed to prevent external mutation.

No fancy validation. No logging. No discounts or tax calculations nobody asked for. Just what the tests need.

That's how you punch a problem.
